<div class="table-wrap"><table class="t"><thead><tr><th>Applicant</th><th>Offer</th><th>Details</th><th>Review</th></tr></thead><tbody>
<?php foreach ($items as $p): ?><tr><td><strong><?= e($p['name']) ?></strong><div class="muted xs"><?= e($p['contact']) ?></div><div class="muted xs"><?= e($p['ref']) ?> · <?= e(ago($p['created_at'])) ?></div></td><td><?= e($p['kind']) ?><div class="muted xs"><?= e($p['location']) ?></div></td><td style="max-width:340px" class="small"><?= nl2br(e(excerpt($p['details'], 300))) ?></td>
<td><form method="post" action="/admin/partners/<?= e($p['ref']) ?>" class="form" style="min-width:230px;gap:8px"><?= csrf_field() ?><div class="row2"><select name="verification"><?php foreach (['Pending', 'Verified', 'Rejected'] as $x) { echo '<option' . ($p['verification'] === $x ? ' selected' : '') . '>' . $x . '</option>'; } ?></select><select name="partner_status"><?php foreach (['Applicant', 'Active', 'Paused', 'Removed'] as $x) { echo '<option' . ($p['partner_status'] === $x ? ' selected' : '') . '>' . $x . '</option>'; } ?></select></div><input name="notes" value="<?= e($p['notes']) ?>" placeholder="Notes"><button class="btn btn-ghost btn-xs">Save</button></form></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="4" class="muted center" style="padding:30px">No partner applications yet.</td></tr><?php endif; ?></tbody></table></div>
